"use client";

import { CATEGORY_BY_ID, formatMoney } from "@/data/demo";
import type { PurchasePlan } from "@/paypilot/types";

/**
 * A deterministic plan from the server. Every number comes from the engine's
 * computed offers; nothing here is generated by a language model.
 */
export function PlanPreview({
  plan,
  onPrepare,
  busy = false,
}: {
  plan: PurchasePlan;
  onPrepare: (plan: PurchasePlan, offerId: string) => void;
  busy?: boolean;
}) {
  const category = CATEGORY_BY_ID[plan.categoryId];
  const recommended = plan.candidates.find((c) => c.offerId === plan.recommendedOfferId) ?? plan.candidates[0];
  const budget = plan.budgetCheck;

  const budgetFits = budget.configured ? budget.ok === true : null;

  return (
    <div className="rounded-xl border border-ink-600 bg-ink-800/60 p-4">
      <div className="flex flex-wrap items-start justify-between gap-2">
        <div>
          <p className="tick text-cyan-400">ENGINE PLAN · {category?.label ?? plan.categoryId}</p>
          <h3 className="mt-1 font-display text-base font-bold text-fog-100">
            {plan.buyerLabel} · {plan.need}
          </h3>
          <p className="mt-0.5 text-[12px] text-fog-400">
            {plan.groupName} · quantity {plan.quantity} · deadline {plan.deadlineDays} days
          </p>
        </div>
        <span className="tick rounded-full border border-lilac-300/40 bg-lilac-300/10 px-2 py-1 text-lilac-400">
          Requires confirmation
        </span>
      </div>

      {budget.configured && budget.ok === false && (
        <p className="mt-3 rounded-lg border border-amber-400/40 bg-amber-400/5 px-3 py-2 text-[12px] leading-relaxed text-amber-400">
          △ {budget.reason} — the recommended share exceeds your remaining planning headroom.
        </p>
      )}
      {budgetFits === true && (
        <p className="mt-3 rounded-lg border border-sage-400/40 bg-sage-400/5 px-3 py-2 text-[12px] leading-relaxed text-sage-400">
          ✓ The recommended share fits inside your planning budget.
        </p>
      )}

      <ul className="mt-3 space-y-2">
        {plan.candidates.map((offer) => (
          <li
            key={offer.offerId}
            className={`flex flex-wrap items-center justify-between gap-3 rounded-lg border px-3 py-2.5 ${
              offer.offerId === recommended?.offerId
                ? "border-coral-500/50 bg-coral-500/5"
                : "border-ink-600 bg-ink-850"
            }`}
          >
            <div className="min-w-0">
              <p className="flex items-center gap-1.5 font-display text-sm font-semibold text-fog-100">
                {offer.sellerName}
                {offer.offerId === recommended?.offerId && (
                  <span className="tick text-coral-600">engine pick</span>
                )}
              </p>
              <p className="mt-0.5 text-[11.5px] text-fog-500">
                {offer.strategyLabel} · {offer.deliveryDays}d delivery · score {offer.score.toFixed(2)}
              </p>
            </div>
            <div className="flex items-center gap-3">
              <span className="font-print text-lg font-semibold tabular-nums text-fog-100">
                {formatMoney(offer.amount)}
              </span>
              <button
                type="button"
                disabled={busy}
                onClick={() => onPrepare(plan, offer.offerId)}
                className={`tick rounded-full border px-3 py-1.5 text-coral-600 transition-colors hover:bg-coral-500 hover:text-ink-950 disabled:cursor-wait disabled:opacity-50 ${
                  offer.offerId === recommended?.offerId
                    ? "bg-coral-500 text-ink-950 border-transparent"
                    : "bg-coral-500/10 border-coral-500/60"
                }`}
              >
                {offer.offerId === recommended?.offerId ? "Prepare recommended" : "Prepare share"}
              </button>
            </div>
          </li>
        ))}
      </ul>

      <details className="mt-3">
        <summary className="tick cursor-pointer text-fog-500 hover:text-fog-300">Why this plan</summary>
        <ol className="mt-2 list-decimal space-y-1 pl-5 text-[12px] leading-relaxed text-fog-400">
          {plan.steps.map((step) => (
            <li key={step}>{step}</li>
          ))}
        </ol>
      </details>

      <p className="mt-3 text-[11px] leading-relaxed text-fog-500">
        This is a simulated engine quote, not a real vendor commitment. Preparing it creates no
        money movement and no PayPal order — a separate code-confirmed step is required.
      </p>
    </div>
  );
}
